    },
    {
      version: 2,
      sql: `
        CREATE TABLE clicks (
          id INTEGER PRIMARY KEY,
          code TEXT NOT NULL,
          clicked_at TEXT NOT NULL,
          referer TEXT,
          FOREIGN KEY (code) REFERENCES links (code)
        );
        CREATE INDEX clicks_code_clicked_at ON clicks (code, clicked_at);
